@_ods_cext.register_operation(_Dialect)
class DiceOp(_ods_ir.OpView):
  r"""
  This operation dices a type implementing the `CuteValueTypeInterface` (ShapeType, IntTupleType,
  LayoutType,...) using a static coordinate attribute. The profile of said coordinate must be
  weakly congruent with that of `input`. Modes associated with an underscore are discarded in the
  result.
  """

  OPERATION_NAME = "cute.dice"

  _ODS_REGIONS = (0, True)

  def __init__(self, input: _ods_ir.Value, coord: _Union[_Any, _ods_ir.Attribute], *, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    _ods_context = _ods_get_default_loc_context(loc)
    attributes["coord"] = (coord if (
    isinstance(coord, _ods_ir.Attribute) or
    not _ods_ir.AttrBuilder.contains('StaticCoordAttr')) else
      _ods_ir.AttrBuilder.get('StaticCoordAttr')(coord, context=_ods_context))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def coord(self) -> _ods_ir.Attribute:
    return self.operation.attributes["coord"]

  @coord.setter
  def coord(self, value: _ods_ir.Attribute):
    if value is None:
      raise ValueError("'None' not allowed as value for mandatory attributes")
    self.operation.attributes["coord"] = value

  @builtins.property
  def result(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

