@_ods_cext.register_operation(_Dialect)
class GetOp(_ods_ir.OpView):
  r"""
  This operation returns a potentially nested mode out of a type implementing
  the `CuteValueTypeInterface`, e.g. a shape, a tuple, a layout,...
  
  The optional `mode` attribute indices are used to select the portion of the
  input type. The number of indices in the `mode` attribute should be less
  than or equal to the depth of type. If `mode` is empty, a copy of the input
  value is returned.
  
  Example:
  
  ```mlir
  %shape = cute.make_shape() : () -> !cute.shape<"(1, (2, 4), 8)">
  %mode0 = cute.get(%shape) <{mode=[1]}>
    : !cute.shape<"(1,(2,4),8)"> -> !cute.shape<"(2,4)">
  %mode1 = cute.get(%shape) <{mode=[1,1]}>
    : !cute.shape<"(1,(2,4),8)"> -> !cute.shape<"4">
  ```
  """

  OPERATION_NAME = "cute.get"

  _ODS_REGIONS = (0, True)

  def __init__(self, result: _ods_ir.Type, input: _ods_ir.Value, *, mode: _Optional[_Union[_Sequence[int], _ods_ir.DenseI32ArrayAttr]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    _ods_context = _ods_get_default_loc_context(loc)
    if mode is not None: attributes["mode"] = (mode if (
        isinstance(mode, _ods_ir.Attribute) or
        not _ods_ir.AttrBuilder.contains('DenseI32ArrayAttr')) else
          _ods_ir.AttrBuilder.get('DenseI32ArrayAttr')(mode, context=_ods_context))
    results = []
    results.append(result)
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def mode(self) -> _Optional[_ods_ir.DenseI32ArrayAttr]:
    if "mode" not in self.operation.attributes:
      return None
    return self.operation.attributes["mode"]

  @mode.setter
  def mode(self, value: _Optional[_ods_ir.DenseI32ArrayAttr]):
    if value is not None:
      self.operation.attributes["mode"] = value
    elif "mode" in self.operation.attributes:
      del self.operation.attributes["mode"]

  @mode.deleter
  def mode(self):
    del self.operation.attributes["mode"]

