@_ods_cext.register_operation(_Dialect)
class GetScalarsOp(_ods_ir.OpView):
  r"""
  Gets the scalars out of a value with CuteValueTypeInterface.
  
  This operation returns only the dynamic scalars when `only_dynamic` is set.
  
  A "scalar" in this context refers to a single value used as part of the
  state of a type. In general, each state value held by a type will be
  considered a scalar if it is printed in the text format. This includes:
  - static integers
  - dynamic integers
  - swizzle parameters
  - scaled basis value (static integer, ratio (num + denom), dynamic integer)
  - scaled basis modes
  - indexed pointer address (always a dynamic value)
  - indexed pointer stride (dynamic integer or dynamic)
  
  Note that underscore values in coordinate types are NOT considered scalars.
  
  Example:
  
  ```mlir
  %1 = cute.get_shape(%0) : (!cute.layout<"(256,?):(?,1)">) -> !cute.shape<"(256,?)">
  %2 = cute.get_scalars(%1) <{only_dynamic}> : (!cute.shape<"(256,?)">) -> i32
  ```
  """

  OPERATION_NAME = "cute.get_scalars"

  _ODS_REGIONS = (0, True)

  def __init__(self, cute_value: _ods_ir.Value, *, only_dynamic: _Optional[bool] = None, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(cute_value)
    _ods_context = _ods_get_default_loc_context(loc)
    if bool(only_dynamic): attributes["only_dynamic"] = _ods_ir.UnitAttr.get(
      _ods_get_default_loc_context(loc))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def cute_value(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def only_dynamic(self) -> bool:
    return "only_dynamic" in self.operation.attributes

  @only_dynamic.setter
  def only_dynamic(self, value):
    if bool(value):
      self.operation.attributes["only_dynamic"] = _ods_ir.UnitAttr.get()
    elif "only_dynamic" in self.operation.attributes:
      del self.operation.attributes["only_dynamic"]

  @only_dynamic.deleter
  def only_dynamic(self):
    del self.operation.attributes["only_dynamic"]

  @builtins.property
  def scalars(self) -> _ods_ir.OpResultList:
    _ods_variadic_group_length = len(self.operation.results) - 1 + 1
    return self.operation.results[0:0 + _ods_variadic_group_length]

