@_ods_cext.register_operation(_Dialect)
class LocalTileOp(_ods_ir.OpView):
  r"""
  The `local_tile` operation tiles a tensor according to a tiler and use a coord to
  index into the remainder, keeping the tile.
  
  This is typical at the CTA level where tiles of data are extracted:
  
  ```mlir
  %data =                                                                   // (  M,  N)
  %crd = cute.make_coord(blockIdx.x,blockIdx.y) : !cute.coord<"(?,?)">
  %cta_data = cute.local_tile(%data, %tile, %crd) : ...                    // (_32,_64)
  ```
  
  Example:
  
  ```mlir
  %0 = cute.local_tile(%alloc, %tile, %coord)
    : (!cute.memref<f32, tmem, align<32>, "(128,128):(65536,1)">,
       !cute.tile<"[128:1;32:1]">,
       !cute.coord<"(_,_)">)
    -> !cute.memref<f32, tmem, align<32>, "(128,32,1,4):(65536,1,0,32)">
  
  %1 = cute.local_tile(%arg0, %shape, %coord_1)
    : (!cute.coord_tensor<"(0,0,0)", "(256,64,1):(1@1,1@0,1@2)">,
       !cute.shape<"(256,64)">,
       !cute.coord<"(0,_,_)">)
    -> !cute.coord_tensor<"(0,0,0)", "(256,64,1,1):(1@1,1@0,0,1@2)">
  ```
  
  Utilizing a flat coordinate '(_)' will flatten the resulting tile.
  
  ```mlir
  %0 = cute.local_tile(%alloc, %tile, %coord)
    : (!cute.memref<f32, tmem, align<32>, "(128,128):(65536,1)">,
       !cute.tile<"[128:1;32:1]">,
       !cute.coord<"(_)">)
    -> !cute.memref<f32, tmem, align<32>, "(128,32,1,4):(65536,1,0,32)">
  
  %1 = cute.local_tile(%arg0, %shape, %coord_1)
    : (!cute.coord_tensor<"(0,0,0)", "(256,64,1):(1@1,1@0,1@2)">,
       !cute.shape<"(256,64)">,
       !cute.coord<"(_)">)
    -> !cute.coord_tensor<"(0,0,0)", "(256,64,1,1,1):(1@1,1@0,0,0,1@2)">
  ```
  
  """

  OPERATION_NAME = "cute.local_tile"

  _ODS_REGIONS = (0, True)

  def __init__(self, input: _ods_ir.Value, tile: _ods_ir.Value, coord: _ods_ir.Value, *, proj: _Optional[_Union[_Any, _ods_ir.Attribute]] = None, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    operands.append(tile)
    operands.append(coord)
    _ods_context = _ods_get_default_loc_context(loc)
    if proj is not None: attributes["proj"] = (proj if (
        isinstance(proj, _ods_ir.Attribute) or
        not _ods_ir.AttrBuilder.contains('CuteCoordAttr')) else
          _ods_ir.AttrBuilder.get('CuteCoordAttr')(proj, context=_ods_context))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def tile(self) -> _ods_ir.Value:
    return self.operation.operands[1]

  @builtins.property
  def coord(self) -> _ods_ir.Value:
    return self.operation.operands[2]

  @builtins.property
  def proj(self) -> _Optional[_ods_ir.Attribute]:
    if "proj" not in self.operation.attributes:
      return None
    return self.operation.attributes["proj"]

  @proj.setter
  def proj(self, value: _Optional[_ods_ir.Attribute]):
    if value is not None:
      self.operation.attributes["proj"] = value
    elif "proj" in self.operation.attributes:
      del self.operation.attributes["proj"]

  @proj.deleter
  def proj(self):
    del self.operation.attributes["proj"]

  @builtins.property
  def result(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

