@_ods_cext.register_operation(_Dialect)
class PrefetchAtomCallOp(_ods_ir.OpView):
  r"""
  `cute.exec_prefetch_atom` op executes a prefetch atom operation with the given operands.
  
  Following src layout of atom are valid
  * ((atom_v, rest_v))
  * ((atom_v))
  * (atom_v)
  
  The `src` operand is variadic:
  - For regular TMA prefetch, `src` is a single tensor.
  - For 2D `tile::gather4` mode, `src` is `[data_coord_tensor, gmem_index_tensor]`.
  
  Examples:
  
  ```mlir
  // Call a prefetch atom operation
  cute.prefetch_atom_call(%copy_tma_load, %src_v)
    : (!cute_nvgpu.atom.tma_load<f16, copy_bits = 131072, mode=tiled, num_cta = 1, g_stride=<"()">,
       %src: !cute.coord_tensor<"(0,0)", "(((64,128),1),1,1,2):(((1@0,1@1),0),0,0,64@0)">)
    -> ()
  
  // gather4 prefetch: data tensor + gmem index tensor
  cute.prefetch_atom_call(%gather4_atom, %src_v, %idx_v)
    : (!cute_nvgpu.atom.tma_load<f16, copy_bits = ..., mode=gather4, num_cta = 1, g_stride=<"()">>,
       !cute.coord_tensor<...>,
       !cute.coord_tensor<...>)
    -> ()
  ```
  """

  OPERATION_NAME = "cute.prefetch_atom_call"

  _ODS_REGIONS = (0, True)

  def __init__(self, atom: _ods_ir.Value, src: _Sequence[_ods_ir.Value], *, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(atom)
    operands.extend(_get_op_results_or_values(src))
    _ods_context = _ods_get_default_loc_context(loc)
    results = []
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def atom(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def src(self) -> _ods_ir.OpOperandList:
    _ods_variadic_group_length = len(self.operation.operands) - 2 + 1
    return self.operation.operands[1:1 + _ods_variadic_group_length]

