@_ods_cext.register_operation(_Dialect)
class ReduceOp(_ods_ir.OpView):
  r"""
  The `cute.reduce` operation reduces elements of a vector according to a given
  shape and reduction operator, optionally guided by a reduction profile and/or a
  predication mask.
  
  The reduction is performed over the dimensions of the input vector as described
  by the provided shape. By default, all dimensions are reduced to a scalar. If a
  reduction profile is specified, it determines which dimensions are kept (marked
  with '_') and which are reduced (marked with an integer or tuple structure). The
  result is either a scalar or a lower-rank vector, along with the reduced shape
  if applicable.
  
  An optional predication vector (of the same size as the input vector) can be
  provided to mask out elements from the reduction, enabling conditional
  reduction.
  
  The reduction operator (e.g., MIN, MAX, ADD, MUL) is specified via the `op`
  attribute.
  
  Examples:
  ```mlir
  // Reduce all elements to a scalar (minimum)
  %reduced = cute.reduce(%input, %shape, %init)
    { op = #cute.reduction_op<MIN> }
    : (vector<20xf32>, !cute.shape<"(4,5)">, f32) -> f32
  
  // Reduce all elements to a scalar (maximum) with predication
  %reduced = cute.reduce(%input, %shape, %init, %pred)
    { op = #cute.reduction_op<MAX> }
    : (vector<20xf32>, !cute.shape<"(4,5)">, f32, vector<20xi1>) -> f32
  
  // Reduce all but the second dimension (profile keeps dimension 1)
  %reduced, %red_shp = cute.reduce(%input, %shape, %init)
    { op = #cute.reduction_op<ADD>, profile = #cute.coord<"(1,_,1)"> }
    : (vector<60xf32>, !cute.shape<"(5,4,3)">, f32) -> (vector<4xf32>, !cute.shape<"(4)>")
  
  // Reduce a nested dimension (profile keeps outer and first inner dimension)
  %reduced, %red_shp = cute.reduce(%input, %shape, %init)
    { op = #cute.reduction_op<MUL>, profile = #cute.coord<"(_,(_,1))"> }
    : (vector<30xf32>, !cute.shape<"(5,(3,2))">, f32) -> (vector<15xf32>, !cute.shape<"(5,3)>")
  ```
  The operation supports both flat and nested shapes and profiles, enabling reductions over complex multidimensional data layouts.
  """

  OPERATION_NAME = "cute.reduce"

  _ODS_REGIONS = (0, True)

  def __init__(self, input: _ods_ir.Value[_ods_ir.VectorType], shape: _ods_ir.Value, init_val: _ods_ir.Value, reduction_op: _Union[_Any, _ods_ir.Attribute], *, predication: _Optional[_ods_ir.Value[_ods_ir.VectorType]] = None, reduction_profile: _Optional[_Union[_Any, _ods_ir.Attribute]] = None, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    operands.append(shape)
    operands.append(init_val)
    if predication is not None: operands.append(predication)
    _ods_context = _ods_get_default_loc_context(loc)
    attributes["reduction_op"] = (reduction_op if (
    isinstance(reduction_op, _ods_ir.Attribute) or
    not _ods_ir.AttrBuilder.contains('cute.CuteReductionOpAttr')) else
      _ods_ir.AttrBuilder.get('cute.CuteReductionOpAttr')(reduction_op, context=_ods_context))
    if reduction_profile is not None: attributes["reduction_profile"] = (reduction_profile if (
        isinstance(reduction_profile, _ods_ir.Attribute) or
        not _ods_ir.AttrBuilder.contains('CuteCoordAttr')) else
          _ods_ir.AttrBuilder.get('CuteCoordAttr')(reduction_profile, context=_ods_context))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value[_ods_ir.VectorType]:
    return self.operation.operands[0]

  @builtins.property
  def shape(self) -> _ods_ir.Value:
    return self.operation.operands[1]

  @builtins.property
  def init_val(self) -> _ods_ir.Value:
    return self.operation.operands[2]

  @builtins.property
  def predication(self) -> _Optional[_ods_ir.Value[_ods_ir.VectorType]]:
    return None if len(self.operation.operands) < 4 else self.operation.operands[3]

  @builtins.property
  def reduction_op(self) -> _ods_ir.Attribute:
    return self.operation.attributes["reduction_op"]

  @reduction_op.setter
  def reduction_op(self, value: _ods_ir.Attribute):
    if value is None:
      raise ValueError("'None' not allowed as value for mandatory attributes")
    self.operation.attributes["reduction_op"] = value

  @builtins.property
  def reduction_profile(self) -> _Optional[_ods_ir.Attribute]:
    if "reduction_profile" not in self.operation.attributes:
      return None
    return self.operation.attributes["reduction_profile"]

  @reduction_profile.setter
  def reduction_profile(self, value: _Optional[_ods_ir.Attribute]):
    if value is not None:
      self.operation.attributes["reduction_profile"] = value
    elif "reduction_profile" in self.operation.attributes:
      del self.operation.attributes["reduction_profile"]

  @reduction_profile.deleter
  def reduction_profile(self):
    del self.operation.attributes["reduction_profile"]

  @builtins.property
  def output(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

  @builtins.property
  def reduced_shape(self) -> _Optional[_ods_ir.OpResult]:
    return None if len(self.operation.results) < 2 else self.operation.results[1]

