@_ods_cext.register_operation(_Dialect)
class ShapeDivOp(_ods_ir.OpView):
  r"""
  Division for Shapes.
  Case Tuple Tuple:
    Perform shape_div element-wise
  Case Tuple Int:
    Fold the division of b across each element of a
    Example: shape_div((4,5,6),40) -> shape_div((1,5,6),10) -> shape_div((1,1,6),2) -> (1,1,3)
  Case Int Tuple:
    Return shape_div(a, product(b))
  Case Int Int:
    Enforce the divisibility condition a % b == 0 || b % a == 0 when possible
    Return a / b with rounding away from 0 (that is, 1 or -1 when a < b)
  
  ```mlir
   %res = cute.shape_div(%a, %b)
      : (!cute.int_tuple<"(4,5)">, !cute.int_tuple<"(40)">) ->  !cute.int_tuple<"(1,1)">
  ```
  """

  OPERATION_NAME = "cute.shape_div"

  _ODS_REGIONS = (0, True)

  def __init__(self, a: _ods_ir.Value, b: _ods_ir.Value, *, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(a)
    operands.append(b)
    _ods_context = _ods_get_default_loc_context(loc)
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def a(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def b(self) -> _ods_ir.Value:
    return self.operation.operands[1]

  @builtins.property
  def result(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

