@_ods_cext.register_operation(_Dialect)
class SizeOp(_ods_ir.OpView):
  r"""
  This operation computes the size of a cute value type by multiplying its dimensions.
  
  The `mode` attribute specifies the nested mode in the type for size calculation.
  It indexes a sub-scope within the input type and returns the size of that sub-scope.
  The rank of `mode` must be less than or equal to the depth of the type.
  If `mode` is empty, the operation calculates the size of the entire type.
  
  ### Examples
  
  ```mlir
  %shape = cute.make_shape() : () -> !cute.shape<"(1,(2,4),9)">
  %size = cute.size(%shape) <{mode=[1]}> : (!cute.shape<"(1,(2,4),9)">) -> !cute.int_tuple<"8">
  ```
  
  In this example, the mode attribute is set to [1], which selects the second dimension of the
  shape (1,(2,4),9). The size of this dimension is calculated as 2 * 4 = 8.
  
  ```mlir
  %shape = cute.make_shape() : () -> !cute.shape<"(1,(2,4),8)">
  %size = cute.size(%shape) : (!cute.shape<"(1,(2,4),8)">) -> !cute.int_tuple<"64">
  ```
  
  In this example, the mode attribute is empty, so the operation calculates the size of the entire
  shape (1,(2,4),8). The size is calculated as 1 * 2 * 4 * 8 = 64.
  """

  OPERATION_NAME = "cute.size"

  _ODS_REGIONS = (0, True)

  def __init__(self, input: _ods_ir.Value, *, mode: _Optional[_Union[_Sequence[int], _ods_ir.DenseI32ArrayAttr]] = None, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    _ods_context = _ods_get_default_loc_context(loc)
    if mode is not None: attributes["mode"] = (mode if (
        isinstance(mode, _ods_ir.Attribute) or
        not _ods_ir.AttrBuilder.contains('DenseI32ArrayAttr')) else
          _ods_ir.AttrBuilder.get('DenseI32ArrayAttr')(mode, context=_ods_context))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def mode(self) -> _ods_ir.DenseI32ArrayAttr:
    return self.operation.attributes["mode"]

  @mode.setter
  def mode(self, value: _ods_ir.DenseI32ArrayAttr):
    if value is None:
      raise ValueError("'None' not allowed as value for mandatory attributes")
    self.operation.attributes["mode"] = value

  @builtins.property
  def result(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

